from django.db import migrations, models


IT_ROOM_CODES = ("IT-301", "IT-302", "IT-303")


def move_it_rooms_and_backfill_types(apps, schema_editor):
    Building = apps.get_model("campus", "Building")
    Floor = apps.get_model("campus", "Floor")
    Room = apps.get_model("campus", "Room")

    it = Building.objects.filter(code="IT").first()

    if it is not None:
        unexpected_floors = list(
            Floor.objects.filter(building=it)
            .exclude(number=3)
            .values_list("number", flat=True)
        )
        if unexpected_floors:
            raise RuntimeError(
                "IT building has unexpected floor(s): "
                + ", ".join(str(number) for number in unexpected_floors)
            )

        it_rooms = Room.objects.filter(floor__building=it)
        unexpected_rooms = list(
            it_rooms.exclude(code__in=IT_ROOM_CODES).values_list("code", flat=True)
        )
        if unexpected_rooms:
            raise RuntimeError(
                "IT building has unexpected room(s): " + ", ".join(unexpected_rooms)
            )

        moving = it_rooms.filter(code__in=IT_ROOM_CODES)
        if moving.exists():
            acad, _ = Building.objects.get_or_create(
                code="ACAD", defaults={"name": "Academic Building"}
            )
            acad_floor3, _ = Floor.objects.get_or_create(building=acad, number=3)
            moving.update(floor=acad_floor3)
        if Room.objects.filter(floor__building=it).exists():
            raise RuntimeError("IT building still contains rooms after guarded move")
        Floor.objects.filter(building=it).delete()
        it.delete()

    Room.objects.update(room_type="CLASSROOM")
    Room.objects.filter(floor__building__code__in=("ONLINE", "UNASSIGNED")).update(
        room_type="OTHER"
    )
    Room.objects.filter(code__startswith="V").update(room_type="OTHER")
    Room.objects.filter(floor__building__code="GYM").update(room_type="GYM")
    Room.objects.filter(code__in=IT_ROOM_CODES).update(room_type="IT_LAB")


def restore_it_rooms_when_still_matching(apps, schema_editor):
    Building = apps.get_model("campus", "Building")
    Floor = apps.get_model("campus", "Floor")
    Room = apps.get_model("campus", "Room")

    matching = Room.objects.filter(
        code__in=IT_ROOM_CODES,
        room_type="IT_LAB",
        floor__building__code="ACAD",
        floor__number=3,
    )
    if not matching.exists():
        return

    it, _ = Building.objects.get_or_create(
        code="IT", defaults={"name": "IT Building"}
    )
    it_floor3, _ = Floor.objects.get_or_create(building=it, number=3)
    matching.update(floor=it_floor3)


